{
  "references": [
    {
      "id": "R1",
      "summary_ko": "말들이 걸을 때 발굽 아래에서 흙이 튀지 않음."
    },
    {
      "id": "R2",
      "summary_ko": "왼쪽 말 배 밑의 끈들이 공중에 떠 있다가 더 또렷하게 나타남."
    },
    {
      "id": "R3",
      "summary_ko": "두 말의 머리가 부자연스럽게 일제히 위아래로 흔들림."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "형태나 존재 변화 가능성이 감지된 미식별 측정 영역."
    },
    {
      "id": "C2",
      "summary_ko": "지면을 이동할 때 쟁기 구조가 왜곡되고 바퀴 세부 요소가 부자연스럽게 변함."
    },
    {
      "id": "C3",
      "summary_ko": "화면이 오른쪽 말을 추적하면서 왼쪽 말이 사라지기 전 몸체 기하구조와 마구가 불일치하게 왜곡되고 융합됨."
    },
    {
      "id": "C4",
      "summary_ko": "주변에 흙이 이는 동안 쟁기의 바퀴 구조와 빔 연결부의 두께 및 방향이 변형됨."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 구체적 대상과 현상이 명시되지 않은 단순 측정 제안이라 관련 여부가 불확실합니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "말 발굽에서 흙이 튀지 않는 문제와 쟁기 구조의 왜곡은 대상과 결함 내용이 서로 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "말 발굽 아래 흙의 부재와 왼쪽 말의 신체/마구 왜곡 및 소실 문제는 서로 다른 결함입니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "말 발굽 아래 흙의 부재와 쟁기 바퀴 및 연결부의 변형 결함은 서로 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 대상이 특정되지 않은 일반적인 측정 제안으로, 말 배 아래 끈의 결함과 동일한지 확정할 수 없습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "왼쪽 말 배 아래 끈의 비정상적 출현과 쟁기 구조의 왜곡은 대상이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "uncertain",
      "reason_ko": "두 설명 모두 왼쪽 말의 마구/끈 관련 왜곡을 언급하지만, R2는 끈의 공중 부유 및 재등장에 초점을 맞추고 C3는 퇴장 시의 전반적 왜곡과 소실을 다루어 동일 결함인지 불확실합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "왼쪽 말 배 아래 끈의 결함과 쟁기 메커니즘의 변형은 대상과 현상이 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 식별된 대상이 없는 측정 가설로 두 말의 머리 움직임 결함과 일치하는지 판단하기 어렵습니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "말들의 머리 흔들림 동기화 문제와 쟁기의 부자연스러운 변형은 대상과 결함이 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "말들의 머리 흔들림 동작 문제와 왼쪽 말의 왜곡 및 화면 소실 현상은 서로 다른 결함입니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "두 말의 머리 움직임 이상과 쟁기 부품의 형태 변화는 대상과 현상이 완전히 다릅니다."
    }
  ]
}
